<?php
namespace App\Manufacturing\Models;
use App\Models\BaseModel; use App\Models\Product; use App\Models\Branch; use App\Models\Warehouse; 
class ManufacturingOrder extends BaseModel { protected $guarded=['id']; protected $casts=['planned_quantity'=>'decimal:6','produced_quantity'=>'decimal:6','scrapped_quantity'=>'decimal:6','reserved_quantity'=>'decimal:6','planned_at'=>'datetime','started_at'=>'datetime','completed_at'=>'datetime','closed_at'=>'datetime']; public function product(){return $this->belongsTo(Product::class);} public function bomVersion(){return $this->belongsTo(BomVersion::class);} public function materials(){return $this->hasMany(ManufacturingOrderMaterial::class);} public function operations(){return $this->hasMany(ManufacturingOperation::class)->orderBy('sequence');} public function statusHistory(){return $this->hasMany(ManufacturingOrderStatusHistory::class);} public function movements(){return $this->hasMany(ManufacturingStockMovement::class);} public function costs(){return $this->hasMany(ManufacturingCostEntry::class);} }
